class RotatingJsonlWriter:
    def __init__(self, out_dir: Path, base: str, max_bytes: int):
        self.out_dir = out_dir
        self.base = base
        self.max_bytes = max_bytes
        self.idx = 1
        self.path, self.fp = self._open_last_or_new()
        self._since_fsync = 0

    def _name(self, i: int) -> str:
        return f"{self.base}_{i:05d}.jsonl"

    def _open_last_or_new(self) -> Tuple[Path, Any]:
        files = sorted(self.out_dir.glob(f"{self.base}_*.jsonl"))
        if files:
            last = files[-1]
            if last.stat().st_size < self.max_bytes:
                stem = last.stem
                try:
                    self.idx = int(stem.split("_")[-1])
                except Exception:
                    self.idx = 1
                return last, open(last, "ab", buffering=0)
            stem = last.stem
            try:
                self.idx = int(stem.split("_")[-1]) + 1
            except Exception:
                self.idx = 1
        path = self.out_dir / self._name(self.idx)
        return path, open(path, "ab", buffering=0)

    def _rotate(self) -> None:
        try:
            self.fp.flush()
            os.fsync(self.fp.fileno())
        except Exception:
            pass
        try:
            self.fp.close()
        except Exception:
            pass
        self.idx += 1
        self.path = self.out_dir / self._name(self.idx)
        self.fp = open(self.path, "ab", buffering=0)
        self._since_fsync = 0

    def write(self, obj: Dict[str, Any]) -> None:
        line = (stable_json_dumps(obj) + "\n").encode("utf-8")
        try:
            size = self.path.stat().st_size
        except Exception:
            size = 0
        if size > 0 and size + len(line) > self.max_bytes:
            self._rotate()
        self.fp.write(line)
        self._since_fsync += 1
        if self._since_fsync >= FSYNC_EVERY_N:
            try:
                self.fp.flush()
                os.fsync(self.fp.fileno())
            except Exception:
                pass
            self._since_fsync = 0

    def close(self) -> None:
        try:
            self.fp.flush()
            os.fsync(self.fp.fileno())
        except Exception:
            pass
        try:
            self.fp.close()
        except Exception:
            pass

