def normalize_text(s: str) -> str:
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    s = re.sub(r"[ \t]+", " ", s)
    s = re.sub(r"\n{3,}", "\n\n", s).strip()
    lines = []
    for line in s.split("\n"):
        line = line.strip()
        if not line:
            lines.append("")
            continue
        if line.startswith("==") and line.endswith("=="):
            continue
        if len(line) <= 1:
            continue
        lines.append(line)
    s = "\n".join(lines)
    s = re.sub(r"\n{3,}", "\n\n", s).strip()
    return s

def looks_hungarian(text: str) -> bool:
    if len(text) < MIN_CHUNK_CHARS:
        return False
    if any(p.search(text) for p in BAD_TEXT_PATTERNS):
        return False
    for p in PII_PATTERNS:
        if p.search(text):
            return False
    hu_chars = sum(text.count(c) for c in "áéíóöőúüűÁÉÍÓÖŐÚÜŰ")
    letters = sum(1 for ch in text if ch.isalpha())
    if letters == 0:
        return False
    ratio = hu_chars / max(1, letters)
    if ratio < 0.002 and len(text) > 2000:
        return False
    return True

def split_paragraphs(text: str) -> List[str]:
    parts = [p.strip() for p in text.split("\n\n")]
    out = []
    for p in parts:
        if not p:
            continue
        if len(p) > MAX_PARAGRAPH_CHARS:
            chunks = [p[i:i + MAX_PARAGRAPH_CHARS].strip() for i in range(0, len(p), MAX_PARAGRAPH_CHARS)]
            out.extend([c for c in chunks if c])
        else:
            out.append(p)
    return out

def split_into_chunks(text: str) -> List[str]:
    paras = split_paragraphs(text)
    chunks: List[str] = []
    buf: List[str] = []
    size = 0
    for p in paras:
        if size + len(p) + 2 <= MAX_CHUNK_CHARS:
            buf.append(p)
            size += len(p) + 2
        else:
            if buf:
                chunks.append("\n\n".join(buf).strip())
            buf = [p]
            size = len(p) + 2
        if len(chunks) >= MAX_DOC_CHUNKS_PER_PAGE:
            break
    if buf and len(chunks) < MAX_DOC_CHUNKS_PER_PAGE:
        chunks.append("\n\n".join(buf).strip())
    chunks = [c for c in chunks if len(c) >= MIN_CHUNK_CHARS]
    return chunks

def sentence_split(text: str) -> List[str]:
    t = re.sub(r"\s+", " ", text).strip()
    if not t:
        return []
    sents = re.split(r"(?<=[\.\?\!])\s+(?=[A-ZÁÉÍÓÖŐÚÜŰ0-9„\"(])", t)
    cleaned = []
    for s in sents:
