        "Ne idézz hosszú szöveget; inkább kérdezz rá olyan tényekre, amelyek egyértelműen következnek a mondatokból.\n"
        "A válasz legyen pontos, rövid, és csak olyan állításokat tartalmazzon, amelyek a forrásmondatokból következnek.\n"
        "Adj meg legalább 2 darab support_sentence_indexes elemet.\n"
        "Nyelv: magyar.\n\n"
        f"Forrás meta: cím={title} url={url}\n\n"
        "Forrásmondatok:\n"
        f"{sent_block}\n\n"
        "Kimenet: egyetlen JSON objektum a megadott sémában."
    )

def build_judge_prompt(candidate_messages: List[Dict[str, str]], sentences: List[str]) -> str:
    sent_block = "\n".join([f"[{i}] {s}" for i, s in enumerate(sentences)])
    msg_block = stable_json_dumps(candidate_messages)
    return (
        "Te egy szigorú minőségellenőr vagy.\n"
        "Értékeld, hogy az asszisztens válasza teljes mértékben következik-e a forrásmondatokból (entailed).\n"
        "Ha bármely állítás nincs a forrásban, akkor entailed=false és a score legfeljebb 40.\n"
        "Ha található hallucináció vagy hozzáadott tény, akkor entailed=false.\n"
        "Visszaadj egyetlen JSON objektumot a sémában.\n\n"
        "Forrásmondatok:\n"
        f"{sent_block}\n\n"
        "Üzenetek:\n"
        f"{msg_block}"
    )

def compute_excerpt_hashes(sentences: List[str], idxs: List[int]) -> List[str]:
    out = []
    for i in idxs:
        if 0 <= i < len(sentences):
            out.append(DEDUP_SHA_PREFIX + sha256_hex_text(sentences[i]))
    return out

def safe_int_list(x: Any) -> List[int]:
    if not isinstance(x, list):
        return []
    out = []
    for v in x:
        try:
            out.append(int(v))
        except Exception:
            continue
    return out

def write_pretrain_records(
    conn: sqlite3.Connection,
    writer: RotatingJsonlWriter,
    title: str,
    page_id: int,
    revid: int,
    url: str,
    chunks: List[str],
) -> int:
    written = 0
    chunk_count = len(chunks)
    for idx, chunk in enumerate(chunks):
        norm = normalize_text(chunk)
        if not looks_hungarian(norm):
            db_inc(conn, "pretrain_filtered", 1)
            continue
        h = DEDUP_SHA_PREFIX + sha256_hex_text(norm)
        if db_seen_text(conn, h):
            db_inc(conn, "pretrain_dupe", 1)
            continue
        rec = {
            "id": str(uuid.uuid4()),
            "created_at": utc_now_iso(),
            "license": LICENSE_WIKIPEDIA,
            "source": {
                "provider": "wikipedia:hu",
                "title": title,
                "page_id": int(page_id),
                "url": url,
                "revision_id": int(revid),
                "chunk_index": int(idx),
                "chunk_count": int(chunk_count),
            },
            "text": norm,
            "text_sha256": h,
        }
        writer.write(rec)
        db_mark_text(conn, h)
        db_inc(conn, "pretrain_written", 1)
        written += 1
    return written

def make_sft_from_chunk(
    client: genai.Client,
    title: str,
    page_id: int,
    revid: int,
    url: str,
    chunk: str,
) -> Optional[Dict[str, Any]]:
    sentences = sentence_split(chunk)
    if len(sentences) < 6:
        return None
    prompt = build_sft_prompt(title, url, chunk, sentences)
    cand = gen_json(client, prompt, SFT_SCHEMA, max_tokens=MAX_OUTPUT_TOKENS)
    msgs = cand.get("messages")
    if not isinstance(msgs, list) or len(msgs) < 2:
        return None
    grounding = cand.get("grounding", {})
    idxs = safe_int_list(grounding.get("support_sentence_indexes"))
    idxs = sorted(set([i for i in idxs if 0 <= i < len(sentences)]))
    if len(idxs) < 2:
        return None
    grounding["support_sentence_indexes"] = idxs
    grounding["support_excerpt_hashes"] = compute_excerpt_hashes(sentences, idxs)
    cand["grounding"] = grounding
    src = cand.get("source", {})
    src["provider"] = "wikipedia:hu"
    src["title"] = title
    src["page_id"] = int(page_id)
    src["url"] = url
    src["revision_id"] = int(revid)
    cand["source"] = src
    cand["license"] = LICENSE_WIKIPEDIA
    cand["id"] = cand.get("id") or str(uuid.uuid4())
    cand["created_at"] = cand.get("created_at") or utc_now_iso()
    q = cand.get("quality", {})
    if not isinstance(q, dict):
        q = {"score": 0, "judge_notes": ""}
    cand["quality"] = q
    judge_prompt = build_judge_prompt(msgs, sentences)
    judge = gen_json(client, judge_prompt, JUDGE_SCHEMA, max_tokens=4096)
    score = int(judge.get("score", 0))
    entailed = bool(judge.get("entailed", False))
    reasons = judge.get("reasons", [])
    if not isinstance(reasons, list):
        reasons = []
    cand["quality"] = {
        "score": score,
        "judge_notes": "; ".join([str(x) for x in reasons][:12]),
    }
    if not entailed:
        return None
    if score < SFT_MIN_SCORE:
        return None
    return cand

def main() -> None:
    random.seed()
    conn = ensure_db()
    client = get_client()
    pretrain_writer = RotatingJsonlWriter(OUT_DIR, "pretrain_hu", MAX_FILE_BYTES)
    sft_writer = RotatingJsonlWriter(OUT_DIR, "sft_hu", MAX_FILE_BYTES)

    commits = 0
    try:
        while True:
            title, page_id = wiki_random_title()
            if db_seen_page(conn, page_id):
                db_inc(conn, "page_dupe", 1)
                continue
            try:
                text, revid, url = wiki_page_plaintext_and_revision(title, page_id)
            except Exception:
                db_inc(conn, "page_fetch_fail", 1)
                continue

            norm = normalize_text(text)
            chunks = split_into_chunks(norm)
            if not chunks:
                db_inc(conn, "page_empty_after_clean", 1)
                db_mark_page(conn, page_id)
                continue

            written = write_pretrain_records(conn, pretrain_writer, title, page_id, revid, url, chunks)
            db_mark_page(conn, page_id)

            if SFT_ENABLED and written > 0:
                produced = 0
                tries = 0
                for chunk in chunks:
                    if produced >= SFT_TARGET_PER_PAGE:
                        break
                    tries += 1
                    if tries > len(chunks) * 2:
                        break
                    if not looks_hungarian(chunk):
                        continue
                    for attempt in range(SFT_MAX_RETRIES):
                        try:
                            rec = make_sft_from_chunk(client, title, page_id, revid, url, chunk)
                            if rec is None:
                                break
                            fp = DEDUP_SHA_PREFIX + sha256_hex_text(stable_json_dumps(rec["messages"]))
                            if db_seen_text(conn, fp):
                                db_inc(conn, "sft_dupe", 1)
                                break
                            sft_writer.write(rec)
                            db_mark_text(conn, fp)
                            db_inc(conn, "sft_written", 1)
                            produced += 1
                            break
                        except Exception:
                            chunked_sleep(attempt)

            db_inc(conn, "pages_processed", 1)
            commits += 1
            if commits % 25 == 0:
                conn.commit()
                pp = db_get(conn, "pages_processed")
                pw = db_get(conn, "pretrain_written")
                sw = db_get(conn, "sft_written")
                print(f"pages={pp} pretrain={pw} sft={sw} pretrain_file={pretrain_writer.path.name} sft_file={sft_writer.path.name}", flush=True)

            time.sleep(SLEEP_BETWEEN_PAGES_SEC)

    finally:
        try:
            conn.commit()
        except Exception:
            pass
        try:
            conn.close()
        except Exception:
            pass
        try:
            pretrain_writer.close()
        except Exception:
            pass
        try:
            sft_writer.close()
        except Exception:
            pass
        try:
            client.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()
